{
    int middlewidth = imgbw.Width * 2 / 5;
    int middleWidth2 = imgbw.Width * 4 / 5;
    int lastHeigh = 0;
    int row = job.row;
    int cutWidth = int.Parse(Math.Round(imgbw.Width * 1.0, 0).ToString());
    int lastCut = 0;
    int newHeight = 0;
    int jobLimitRow = job.row + 6;
    string status = "Open";
    for (int i = job.i; i < imgbw.Height && (LimitRows == -1 || row<LimitRows) &&  row < jobLimitRow; i++)
    {
        job.i = i;
        job.row = row;
        if(job.page==0 && row>5)
        {
            var isAtama = false;
            foreach(var rowX in Rows)
            {
                foreach(var cellX in rowX.cells)
                {
                    if(cellX.worInverted.IndexOf("מסמך התאמה") >-1)
                    {
                        isAtama = true;
                    }
                }
            }
            if(!isAtama)
            {
                i = imgbw.Height - 1;
                status = "Done";
                break;
            }
        }
        try
        {
            Color pixel = bwImageBorders.GetPixel(middlewidth, i);
            if (!isAbsBlack(pixel))
            {
                if (isLine(bwImageBorders, i, middlewidth, 12) && isLine(bwImageBorders, i, middleWidth2, 12))
                {

                    int prevLine = checkPrevLine(middlewidth, middleWidth2, i, bwImageBorders, 12);

                    lastHeigh = prevLine;
                    if (lastHeigh < i && (i - lastHeigh) > 12)
                    {

                        int cutHeight = int.Parse(Math.Round((i - lastHeigh) * 1.0, 0).ToString());

                        var Row = CropRow(imgbw, cutWidth, cutHeight, 0, lastHeigh, "" + imagePath, row.ToString(), false);
                        var Row2 = CropRow(bwImageBorders, cutWidth, cutHeight, 0, lastHeigh, "" + imagePath, row + "borders", false);
                        Row newRow = new Row() { cells = new List<Cell>(), img = Row, imgBw = Row2, Height = cutHeight, Width = cutWidth, X = 0, Y = lastHeigh, num = row };
                        var cellRow = new Cell() { Height = cutHeight, Width = cutWidth, img = Row, imgBw = Row2, X = 0, Y = lastHeigh, word = "", wordEn = "", num = 0 };


                        int middleHeight = lastHeigh + 3;

                        int middleTest = Math.Max(int.Parse(Math.Round((i * 1.0 - lastHeigh * 1.0 - 3.0), 0).ToString()), 10);
                        int lastLineVet = 0;
                        int cell = 0;
                        bool hasContent = false;
                        for (var w = 0; w < bwImageBorders.Width; w++)
                        {

                            if (isLineVert(bwImageBorders, middleHeight, w, middleTest))
                            {
                                lastLineVet = checkPrevVertLine(middleHeight, w, bwImageBorders, middleTest);
                                if (w - lastLineVet > 10 || lastLineVet == 0)
                                {

                                    ////!!!for tests remove reading!!!
                                    int cutWidthCell = int.Parse(Math.Round((w - lastLineVet) * 1.0, 0).ToString());
                                    var Cell = CropCell(imgbw, cutWidthCell - 2, cutHeight - 2, lastLineVet + 2, lastHeigh + 2, "" + imagePath, row.ToString(), cell.ToString(), false);
                                    var CellInverted = CropCell(bwImageInverted, cutWidthCell - 2, cutHeight - 2, lastLineVet + 2, lastHeigh + 2, "iverted" + imagePath, row.ToString(), cell.ToString(), false);
                                    var cellInternal = new Cell() { Height = cutHeight, Width = cutWidthCell, img = Cell, imgBw = CellInverted, X = lastLineVet, Y = lastHeigh, word = "", wordEn = "", num = cell };

                                    imagePath = imagePath.Replace(".png", "");


                                    var text = GetText(Cell);
                                    var textInverted = GetText(CellInverted);
                                    var textEn = GetTextEn(Cell);
                                    var textEnInverted = GetTextEn(CellInverted);

                                    cellInternal.word = text;
                                    cellInternal.worInverted = textInverted;
                                    cellInternal.wordEn = textEn;
                                    cellInternal.wordEnInverted = textEnInverted;




                                    cell++;
                                    newRow.cells.Add(cellInternal);
                                    ////!!!for tests remove reading!!!
                                }
                            }

                        }
                        if (newRow.cells.Count == 0 || !hasContent)
                        {
                            var text = GetText(Row);
                            var textEn = GetTextEn(Row);
                            var textIvereted = GetText(Row2);
                            var textEnInverted = GetTextEn(Row2);
                            cellRow.word = text;
                            cellRow.wordEn = textEn;
                            cellRow.worInverted = textIvereted;
                            cellRow.wordEnInverted = textEnInverted;
                            newRow.cells.Add(cellRow);

                        }
                        Rows.Add(newRow);
                        lastCut = i;
                        row++;
                        job.row = row;
                        job.i = i+1;
                    }

                }
            }
        }
        catch(Exception ex1)
        {
            var message = ex1;
        }
        if (i >= imgbw.Height - 1 || job.i >= imgbw.Height - 1)
            status = "Done";
    }
    job.status = status;
    return job;
}

