{
    var memberId = Convert.ToInt32(newJob.MemberId);
    var member = _context.Members.FirstOrDefault(m => m.Id == memberId);

    var offsetTimespan = member.TimezoneOffsetMinutes.HasValue
        ? TimeSpan.FromMinutes(member.TimezoneOffsetMinutes.Value)
        : Constants.DefaultTimezoneOffset;

    var dayBegin = Constants.WorkdayBeginUtc - offsetTimespan;
    var dayEnd = Constants.WorkdayEndUtc - offsetTimespan;

    var jobs = _context.Jobs
        .Where(j => j.MemberId == newJob.MemberId)
        .Where(j => j.start.HasValue && j.end.HasValue)
        .Where(j => !j.Finished.HasValue || !j.Finished.Value)
        .OrderBy(j => j.start)
        .ToList();


    var startDate = finishedJob.ActualEnd ?? DateTime.Now;
    newJob.Deadline = CalculateDeadlineDate(startDate, nextStage.Deadline.Value, nextStage.DeadlineUnit, offsetTimespan);

    while (true)
    {
        var endDate = startDate + TimeSpan.FromMinutes(nextStage.DurationMinutes.Value);
        var overlappingJobs = jobs.Where(j => j.start <= endDate && j.end >= startDate).ToList();
        if (!overlappingJobs.Any() && endDate.TimeOfDay < dayEnd)
        {
            newJob.start = startDate;
            newJob.end = endDate;
            return;
        }

        if (overlappingJobs.Any())
        {
            startDate = overlappingJobs.Select(j => j.end).Max().Value;
        }
        else
        {
            startDate = startDate.AddBusinessDays(1).Date + dayBegin;
        }

    }


}

{
    List<ActionWithStates> actionWithStates = new List<ActionWithStates>();
    List<StateSummary> EmptyStates  = GameHelpers.CreateEmptyStates(_context);
    List<Actions> actions =  _context.Actions.Where(a => a.ParentId == parent_id && a.Language == language).OrderBy(a=>a.OrderNum).ToList();
    var currentUser = HttpContext.User;
    Users myuser = GameHelpers.GetUserByContext(currentUser, _context);
    foreach (Actions action in actions)
    {
        ActionWithStates actionExt = new ActionWithStates();
        actionExt.status = "Ok";
        actionExt.action = action;
        actionExt.statesRequirements = new List<StateRequirements>();
        actionExt.errors = new List<string>();
        foreach (StateSummary state in EmptyStates)
        {
            List<ActionToStatesDefs> statesToAction = _context.ActionToStatesDefs.Where(a => a.ActionId == action.Id.ToString() && a.StateId == state.Id.ToString()).ToList();
            foreach (ActionToStatesDefs actReq in statesToAction)
            {
                StateRequirements myactionRequirements = GameHelpers.CreateStateRequirement(actionExt, actReq, state);
            }
        }
        var stage = _context.Stages.Where(a => a.ParentId == action.Id.ToString()).FirstOrDefault();
        if(stage!=null)
        {
            actionExt.hasStages = true;
        }
        else
        {
            actionExt.hasStages = false;
        }
        actionExt.canEdit = false;
        if (myuser!=null && myuser.IsAdmin==true)
        {
            actionExt.canEdit = true;
        }
        actionWithStates.Add(actionExt);
    }
    return await Task.Run(()=>actionWithStates);
}

